package cl.duoc.dsy1107.bffservice.service;
import org.springframework.beans.factory.annotation.Value; import org.springframework.core.ParameterizedTypeReference; import org.springframework.http.MediaType; import org.springframework.stereotype.Service; import org.springframework.web.client.RestClient; import java.util.*;
@Service public class BackendClient {
 private final RestClient ot; private final RestClient events; private final RestClient notifications;
 public BackendClient(RestClient.Builder builder,@Value("${app.services.ot}") String otUrl,@Value("${app.services.events}") String evUrl,@Value("${app.services.notifications}") String noUrl){ot=builder.baseUrl(otUrl).build();events=builder.baseUrl(evUrl).build();notifications=builder.baseUrl(noUrl).build();}
 public Object getOts(){return ot.get().uri("/api/ots").retrieve().body(Object.class);} public Object getOt(String id){return ot.get().uri("/api/ots/{id}",id).retrieve().body(Object.class);} public Object getItems(String id){return ot.get().uri("/api/ots/{id}/items",id).retrieve().body(Object.class);} public Object createOt(Object body){return ot.post().uri("/api/ots").contentType(MediaType.APPLICATION_JSON).body(body).retrieve().body(Object.class);} public Object updateOt(String id,Object body){return ot.put().uri("/api/ots/{id}",id).contentType(MediaType.APPLICATION_JSON).body(body).retrieve().body(Object.class);} public void deleteOt(String id){ot.delete().uri("/api/ots/{id}",id).retrieve().toBodilessEntity();} public Object addItem(String id,Object body){return ot.post().uri("/api/ots/{id}/items",id).contentType(MediaType.APPLICATION_JSON).body(body).retrieve().body(Object.class);} public void deleteItem(String id,Long itemId){ot.delete().uri("/api/ots/{id}/items/{itemId}",id,itemId).retrieve().toBodilessEntity();}
 public Object events(String id){return events.get().uri("/api/events/ot/{id}",id).retrieve().body(Object.class);} public Object notifications(String id){return notifications.get().uri("/api/notifications/ot/{id}",id).retrieve().body(Object.class);}
}
